[4353]={nameES="Dol Amroth - The Armoury",objectivesES={"Defeated bands of corsairs","Defeat Jabbur","Jabbur has been defeated. The armoury is secured.","Retake the armoury.","Dol Amroth - The Armoury","You are retaking the armoury of Dol Amroth!"}},
[4354]={nameES="Dol Amroth - The Bank",objectivesES={"Defeated bands of corsairs","You are retaking the bank of Dol Amroth!","Defeat Khabec","Dol Amroth - The Bank","Retake the bank.","Khabec has been defeated. The bank is secured."}},
[4355]={nameES="Dol Amroth - The Docks",objectivesES={"Defeated bands of corsairs","You are retaking the docks of Dol Amroth!","Darîjan has been defeated. The docks are secure.","Dol Amroth - The Docks","Retake the docks.","Defeat Darîjan"}},
[4356]={nameES="Dol Amroth - The Great Hall",objectivesES={"Defeated bands of corsairs","Defeat Mîkhin","Mîkhin has been defeated. The Great Hall is secure.","Retake the Great Hall.","You are retaking the Great Hall of Dol Amroth!","Dol Amroth - The Great Hall"}},
[4357]={nameES="Dol Amroth - The Library",objectivesES={"Dol Amroth - The Library","Retake the library.","Urbin has been defeated. The library is secure.","Defeat Urbin","You are retaking the library of Dol Amroth!"}},
[4358]={nameES="Dol Amroth - The Mason",objectivesES={}},
[4359]={nameES="Dol Amroth - The Swan-knights",objectivesES={"Kesekhos has been defeated. The Swan-knight Barracks are secure.","Retake the barracks of the Swan-knights.","Defeat Kesekhos","Dol Amroth - The Swan-knights","Defeated bands of Corsairs","You are retaking the barracks of the Swan-knights of Dol Amroth!"}},
[4360]={nameES="Dol Amroth - The Warehouse",objectivesES={"Retake the warehouse.","Defeated bands of corsairs","Defeat Dabardon","You are retaking the warehouse of Dol Amroth!","Dol Amroth - The Warehouse","Dabardon has been defeated. The warehouse is secure."}},
[4361]={nameES="Dol Amroth - Training Exercise",objectivesES={"The city watch of Dol Amroth is performing a training exercise in which they wish you to participate.\
\
<rgb=#FF0000>Once accepted, this quest cannot be cancelled. You must complete the training exercise to finish the quest.</rgb>","The city guard has asked you to join it on a patrol of the immediate area.","Returning from the exercise, you discover the city has been taken!","Dol Amroth - Training Exercise","Speak to Beriaudur and start the training exercise"}},
